from pathlib import Path
path = Path('src/main.tsx')
path.write_text('''// Preconfigured Gravity UI setup is ALREADY wired here (both CSS imports + ThemeProvider).
import '@gravity-ui/uikit/styles/fonts.css';
import '@gravity-ui/uikit/styles/styles.css';

import React, { useState } from 'react';
import ReactDOM from 'react-dom/client';
import { ThemeProvider } from '@gravity-ui/uikit';

import { App } from './App';

const themeStorageKey = 'theme';

function readStoredTheme(): 'light' | 'dark' {
  try {
    return window.localStorage.getItem(themeStorageKey) === 'dark' ? 'dark' : 'light';
  } catch {
    return 'light';
  }
}

function storeTheme(theme: 'light' | 'dark') {
  try {
    window.localStorage.setItem(themeStorageKey, theme);
  } catch {
    // localStorage may be unavailable, the selected theme still works until reload.
  }
}

const initialTheme = readStoredTheme();

ReactDOM.createRoot(document.getElementById('root')"'!).render(
  <React.StrictMode>
    <ThemeProvider theme={initialTheme}>
      <App onThemeChange={storeTheme} />
    </ThemeProvider>
  </React.StrictMode>,
);
'"''')
path = Path('src/App.tsx')
path.write_text('''import React from 'react';
import { Switch, useTheme } from '@gravity-ui/uikit';

interface AppProps {
  onThemeChange: (theme: 'light' | 'dark') => void;
}

export function App({ onThemeChange }: AppProps) {
  const theme = useTheme();
  const isDark = theme === 'dark';

  return (
    <div style={{ padding: 24 }}>
      <Switch
        checked={isDark}
        content={isDark ? 'Тёмная тема' : 'Светлая тема'}
        onUpdate={(checked) => onThemeChange(checked ? 'dark' : 'light')}
      />
    </div>
  );
}
''')
PY
npm run build"

